package ec.dmt.admin.school;
import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/courses") public class CourseController { private final CourseRepository repo; public CourseController(CourseRepository repo){this.repo=repo;} @GetMapping public List<View> list(){return repo.findAll().stream().map(View::of).toList();} @PostMapping public ResponseEntity<View> create(@Valid @RequestBody Input in){Course c=repo.save(new Course(in.name().trim(),in.active()));return ResponseEntity.status(201).body(View.of(c));} @PutMapping("/{id}") public View update(@PathVariable Long id,@Valid @RequestBody Input in){Course c=find(id);c.update(in.name().trim(),in.active());return View.of(repo.save(c));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.delete(find(id));} private Course find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Curso no encontrado"));} public record Input(@NotBlank String name,boolean active){} public record View(Long id,String name,boolean active){static View of(Course c){return new View(c.getId(),c.getName(),c.isActive());}} }
